cat >> src/orchestration/orchestratorHelpers.ts <<'EOF'

// A round that reported nothing adds nothing, so the total stays undefined only when no round reported.
export function sumUsage(total: UsageMetadata | undefined, next: UsageMetadata | undefined): UsageMetadata | undefined {
  if (total === undefined) return next;
  if (next === undefined) return total;
  return {
    inputTokens: total.inputTokens + next.inputTokens,
    outputTokens: total.outputTokens + next.outputTokens,
    totalTokens: total.totalTokens + next.totalTokens,
  };
}
EOF
